# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List
from rosterkit.models import Student


def _sort_key(student: Student):
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )


def _row_line(number: int, row: List[Student]) -> str:
    names = [f"{s.last_name}, {s.first_name}" for s in row]
    return f"Row {number}: " + " | ".join(names)


def _chunks(items, size):
    return [
        items[i:i + size]
        for i in range(0, len(items), size)
    ]


# ---
def seating_rows(students, seats_per_row: int) -> List[str]:
    """One line per row, sorted by last name."""
    if seats_per_row <= 0 or not students:
        raise ValueError("need students and seats > 0")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, seats_per_row)
    return [_row_line(i, r) for i, r in enumerate(rows, 1)]

